from collections import defaultdict

# Simulated log entries: (source_ip, event_type)
logs = [
    ("10.0.0.5",  "auth_fail"),
    ("10.0.0.5",  "auth_fail"),
    ("10.0.0.5",  "auth_success"),
    ("10.0.0.9",  "auth_fail"),
    ("192.168.1.1", "port_scan"),
]

# defaultdict(int): automatically initialises missing keys to 0
fail_counts = defaultdict(int)           # No KeyError on first access
for ip, event in logs:
    if event == "auth_fail":
        fail_counts[ip] += 1             # Increment without checking existence

print(dict(fail_counts))                 # {'10.0.0.5': 2, '10.0.0.9': 1}

# Flag IPs with >1 auth failure as potential brute-force
BRUTEFORCE_THRESHOLD = 2
suspects = {ip for ip, count in fail_counts.items() if count >= BRUTE_FORCE_THRESHOLD}
print(suspects)                          # {'10.0.0.5'}

# Dict comprehension: invert a mapping (value -> key)
SERVICES = {22: "SSH", 80: "HTTP", 443: "HTTPS"}
PORTS_BY_SERVICE = {v: k for k, v in SERVICES.items()}  # Flip keys and values
print(PORTS_BY_SERVICE["SSH"])           # 22

# Nested dict: group events by IP then by type
event_map = defaultdict(lambda: defaultdict(int))
for ip, event in logs:
    event_map[ip][event] += 1
print(dict(event_map["10.0.0.5"]))      # {'auth_fail': 2, 'auth_success': 1}

package main

import "fmt"

// modifyValue takes a plain int — Go passes by value, so this is a copy
func modifyValue(x int) {
	x = 99                         // Only modifies the local copy
}

// modifyPointer takes a pointer to int — can modify the original
func modifyPointer(p *int) {
	*p = 99                        // Dereference p and write to the address it holds
}

// buildPayload demonstrates a pointer receiver on a struct
type Payload struct {
	Data []byte
	Size int
}

// Pointer receiver: modifications affect the original Payload
func (p *Payload) AppendByte(b byte) {
	p.Data = append(p.Data, b)     // append may reallocate; pointer receiver ensures caller sees new slice
	p.Size = len(p.Data)
}

func main() {
	x := 42
	modifyValue(x)
	fmt.Println(x)                 // 42 — unchanged

	modifyPointer(&x)              // & takes the address of x
	fmt.Println(x)                 // 99 — changed via pointer

	addr := &x                    // addr is of type *int
	fmt.Printf("address: %p, value: %d\n", addr, *addr)  // %p prints address, *addr dereferences

	payload := Payload{Data: []byte{}}
	payload.AppendByte(0x41)       // Pointer receiver called on value — Go handles automatically
	payload.AppendByte(0x42)
	fmt.Println(payload.Data)      // [65 66] — 0x41 0x42
}

import json
import subprocess
import time
from dataclasses import dataclass, field
from typing import Optional

@dataclass
class TTPResult:
    technique_id: str
    name:         str
    success:      bool
    output:       str
    duration_ms:  float
    timestamp:    str = field(default_factory=lambda: time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()))

def ttp_system_info() -> TTPResult:       # T1082 — System Information Discovery
    start = time.time()
    try:
        out = subprocess.check_output(["uname", "-a"], text=True, timeout=10)
        return TTPResult("T1082", "System Information Discovery", True, out.strip(),
                         (time.time() - start) * 1000)
    except Exception as e:
        return TTPResult("T1082", "System Information Discovery", False, str(e),
                         (time.time() - start) * 1000)

def ttp_process_list() -> TTPResult:      # T1057 — Process Discovery
    start = time.time()
    try:
        out = subprocess.check_output(["ps", "aux"], text=True, timeout=10)
        return TTPResult("T1057", "Process Discovery", True, out[:500],  # Truncate to 500 chars
                         (time.time() - start) * 1000)
    except Exception as e:
        return TTPResult("T1057", "Process Discovery", False, str(e),
                         (time.time() - start) * 1000)

# Registry: technique ID -> simulation function
REGISTRY: dict = {
    "T1082": ttp_system_info,
    "T1057": ttp_process_list,
}

def run_techniques(ids: list[str]) -> list[TTPResult]:
    results = []
    for tid in ids:
        fn = REGISTRY.get(tid)
        if fn is None:
            print(f"[-] No simulation for {tid}")
            continue
        print(f"[*] Running {tid}")
        results.append(fn())              # Call the mapped function
    return results

